"use client"

import type { DocumentItemFieldDefinition } from "@/lib/document-templates"
import type { Ref } from "@/lib/provenance"
import { CheckGlyph, RationalePopover } from "@/components/pipeline/document-detail/rationale-popover"
import type { FieldCheck } from "@/components/pipeline/document-detail/check-types"
import { Crosshair, Plus, Trash2 } from "lucide-react"
import { useRef, useState } from "react"

type Row = { id: number; values: Record<string, unknown> }

const cellInputClass = "w-full min-w-0 rounded-sm border-0 bg-transparent px-2 py-1.5 text-sm text-slate-800 outline-none focus:bg-emerald-50 focus:ring-1 focus:ring-inset focus:ring-emerald-500"

const hasValue = (value: unknown) => value !== undefined && value !== null && value !== ""

/** Line items as an actual grid — one row per item, one column per field, cells that edit in
 * place — rather than a stack of bordered cards repeating every label. The header row plus
 * light cell dividers are what make it read as a small spreadsheet instead of a form.
 *
 * Columns are the template's real schema (itemFields), never invented ones — but a column the
 * model never actually extracted anything into, across every row of THIS document, is dropped
 * rather than shown as a wall of empty cells (a required column is the one exception: it stays
 * visible even empty, since a missing required value is itself worth seeing). On a document with
 * no line items yet (a fresh row for someone to fill in by hand), nothing has "not been
 * extracted" yet, so every column shows. */
export function LineItemsEditor({ fieldKey, itemFields, initialRows, provenanceItems, onFocusSource, checks = [], onEscalate }: {
  fieldKey: string
  itemFields: DocumentItemFieldDefinition[]
  initialRows: Array<Record<string, unknown>>
  provenanceItems?: (Ref | null)[]
  onFocusSource?: (target: { page: number; bbox: Ref["bbox"]; quote: string }) => void
  checks?: FieldCheck[]
  onEscalate?: (check: FieldCheck) => void
}) {
  const [rows, setRows] = useState<Row[]>(() => {
    const seed = initialRows.length ? initialRows : [{}]
    return seed.map((values, index) => ({ id: index, values }))
  })
  const [openCell, setOpenCell] = useState<string | null>(null)
  const cellRefs = useRef(new Map<string, HTMLInputElement | HTMLSelectElement>())
  const columns = initialRows.length
    ? itemFields.filter((item) => item.required || initialRows.some((row) => hasValue(row[item.key])))
    : itemFields

  const addRow = () => setRows((current) => [...current, { id: (current.at(-1)?.id ?? -1) + 1, values: {} }])
  const removeRow = (id: number) => setRows((current) => (current.length > 1 ? current.filter((row) => row.id !== id) : current))

  return <div className="overflow-hidden rounded-lg border border-slate-200">
    <div className="overflow-x-auto">
      <table className="w-full min-w-max border-collapse text-sm">
        <thead>
          <tr className="bg-slate-50">
            {columns.map((item) => <th key={item.key} scope="col" className={`border-b border-slate-200 px-2 py-1.5 text-xs font-semibold uppercase tracking-wide text-slate-500 ${item.type === "number" ? "text-right" : "text-left"}`}>
              {item.label}{item.required ? " *" : ""}
            </th>)}
            <th scope="col" className="w-8 border-b border-slate-200" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => {
            const rowRef = provenanceItems?.[index] ?? null
            return <tr key={row.id} className="group even:bg-slate-50/50 hover:bg-emerald-50/40">
            {columns.map((item) => {
              const inputId = `${fieldKey}-${row.id}-${item.key}`
              const name = `${fieldKey}[${index}][${item.key}]`
              const raw = row.values[item.key]
              const fieldPath = `${fieldKey}[${index}].${item.key}`
              const cellChecks = checks.filter((check) => check.fields.includes(fieldPath))
              const checkDescriptionId = `${fieldPath}-check-description`
              const cellId = `${fieldKey}-${row.id}-${item.key}`
              return <td key={item.key} className="relative border-b border-slate-100 p-0">
                {item.type === "boolean" ? (
                  <label className="flex h-full items-center justify-center gap-1.5 px-2 py-1.5 text-xs text-slate-600">
                    <input id={inputId} name={name} type="checkbox" aria-describedby={cellChecks.length ? checkDescriptionId : undefined} className="h-3.5 w-3.5 accent-emerald-600" value="true" defaultChecked={raw === true} />
                  </label>
                ) : item.type === "enum" ? (
                  <div className="relative flex items-center">
                    <select ref={(element) => { if (element) cellRefs.current.set(cellId, element); else cellRefs.current.delete(cellId) }} id={inputId} name={name} aria-describedby={cellChecks.length ? checkDescriptionId : undefined} defaultValue={typeof raw === "string" ? raw : ""} className={`${cellInputClass} appearance-none ${cellChecks.length ? "pr-8" : ""}`}>
                      <option value="">—</option>
                      {item.options?.map((option) => <option key={option} value={option}>{option}</option>)}
                    </select>
                    <span className="absolute right-1 top-1/2 -translate-y-1/2"><CheckGlyph checks={cellChecks} onOpen={() => setOpenCell(cellId)} /></span>
                  </div>
                ) : (
                  <div className="relative flex items-center">
                    <input ref={(element) => { if (element) cellRefs.current.set(cellId, element); else cellRefs.current.delete(cellId) }} id={inputId} name={name} type={item.type === "number" ? "number" : item.type === "date" ? "date" : "text"} step={item.type === "number" ? "any" : undefined} aria-describedby={cellChecks.length ? checkDescriptionId : undefined}
                      className={`${cellInputClass} ${item.type === "number" ? "text-right tabular-nums" : ""} ${cellChecks.length ? "pr-8" : ""}`}
                      defaultValue={typeof raw === "string" || typeof raw === "number" ? String(raw) : ""} />
                    <span className="absolute right-1 top-1/2 -translate-y-1/2"><CheckGlyph checks={cellChecks} onOpen={() => setOpenCell(cellId)} /></span>
                  </div>
                )}
                {cellChecks.length > 0 && <span id={checkDescriptionId} className="sr-only">{cellChecks.map((check) => check.stale ? `${check.message} Not rechecked after this edit.` : check.message).join(" ")}</span>}
                {openCell === cellId && <RationalePopover rationale={null} mismatchChecks={cellChecks} onClose={() => setOpenCell(null)} onFix={() => cellRefs.current.get(cellId)?.focus()} onEscalate={onEscalate} />}
              </td>
            })}
            <td className="border-b border-slate-100 px-1 text-center">
              <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100">
                {rowRef && onFocusSource && (
                  <button type="button" aria-label="View source" title="View source in document"
                    className="rounded p-1 text-emerald-500 hover:bg-emerald-50 hover:text-emerald-700"
                    onClick={() => onFocusSource({ page: rowRef.page, bbox: rowRef.bbox, quote: rowRef.quote })}>
                    <Crosshair className="h-3.5 w-3.5" />
                  </button>
                )}
                <button type="button" aria-label="Remove row" title="Remove row" disabled={rows.length <= 1}
                  className="rounded p-1 text-slate-500 hover:bg-red-50 hover:text-red-700 disabled:pointer-events-none disabled:opacity-0"
                  onClick={() => removeRow(row.id)}>
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            </td>
          </tr>})}
        </tbody>
      </table>
    </div>
    <button type="button" onClick={addRow}
      className="flex w-full items-center gap-1.5 border-t border-slate-200 bg-slate-50/50 px-2.5 py-1.5 text-xs font-medium text-slate-500 hover:bg-emerald-50 hover:text-emerald-700">
      <Plus className="h-3.5 w-3.5" />Add row
    </button>
  </div>
}
=====
import { tokenSetRatio } from "@/lib/suppliers/normalize"
import type { CheckResult } from "@/lib/checks/types"

/** #206 (map #177's ticket 15): per-line-consumption of a PO against every invoice matched to it.
 * Per-line pairing (invoice line N ↔ PO line N) is explicitly out of scope — a second matching
 * engine. Instead, each invoice line is assigned to its best-matching PO line by description
 * similarity (no item code/SKU exists in this schema), quantities from every matched invoice are
 * summed per PO line, and the group is flagged only once cumulative consumption exceeds the
 * ordered quantity by more than the workspace's tolerance. A description with no PO-line match
 * above MATCH_THRESHOLD is not judged — an unmatched item is a matching problem, not a
 * consumption one, and inventing a comparison would teach the reviewer to distrust the check. */

const MATCH_THRESHOLD = 0.6

export type PoLineConsumptionInput = {
  poLineItems: Array<{ description: string | null; quantity: number | null }>
  /** Every line item from every invoice matched to this PO, including the invoice under review —
   * tagged with the source document so the message can name where the overage came from. */
  invoiceLineItems: Array<{ documentId: string; rowIndex: number; description: string | null; quantity: number | null }>
  /** Acceptable overage over the ordered quantity, as a percentage (5 = 5% over is still fine). */
  tolerancePercent: number
  /** The document under review — only its own line items are addressed in `fields`, so a
   * mismatch surfaced while reviewing one invoice never points the reviewer at another
   * document's cells. */
  currentDocumentId: string
}

function bestPoLineIndex(description: string | null, poDescriptions: Array<string | null>): number | null {
  let bestIndex: number | null = null
  let bestScore = MATCH_THRESHOLD
  poDescriptions.forEach((candidate, index) => {
    const score = tokenSetRatio(description, candidate)
    if (score > bestScore) { bestScore = score; bestIndex = index }
  })
  return bestIndex
}

export function checkPoLineConsumption(input: PoLineConsumptionInput): CheckResult | null {
  const poDescriptions = input.poLineItems.map((item) => item.description)
  const consumedByLine = new Map<number, number>()
  const contributingRowsByLine = new Map<number, number[]>()

  for (const item of input.invoiceLineItems) {
    if (item.quantity === null) continue
    const lineIndex = bestPoLineIndex(item.description, poDescriptions)
    if (lineIndex === null) continue
    consumedByLine.set(lineIndex, (consumedByLine.get(lineIndex) ?? 0) + item.quantity)
    if (item.documentId === input.currentDocumentId) {
      const rows = contributingRowsByLine.get(lineIndex) ?? []
      rows.push(item.rowIndex)
      contributingRowsByLine.set(lineIndex, rows)
    }
  }

  const issues: string[] = []
  const fields = new Set<string>()

  input.poLineItems.forEach((poLine, index) => {
    if (poLine.quantity === null) return
    const consumed = consumedByLine.get(index)
    if (consumed === undefined) return
    const allowance = poLine.quantity * (1 + input.tolerancePercent / 100)
    if (consumed <= allowance) return
    const rows = contributingRowsByLine.get(index)
    if (!rows?.length) return // this invoice's own lines didn't push it over — not this document's problem to flag
    issues.push(`"${poLine.description ?? `PO line ${index + 1}`}": ordered ${poLine.quantity}, invoiced ${consumed} across matched invoices (tolerance ${input.tolerancePercent}%)`)
    for (const row of rows) fields.add(`line_items[${row}].quantity`)
  })

  if (!issues.length) return null
  return { checkCode: "po_line_consumption", status: "fail", message: issues.join("; "), fields: [...fields] }
}

