      </button>
    </div>
    <p className="mt-1 text-xs text-slate-700">
      {link
        ? <>Comparing against <strong className="font-semibold text-slate-900">{describe(link)}</strong>{link.kind === "auto" ? " — matched by the PO number on the invoice, not yet confirmed." : " — confirmed."} Pick a PO line for each row below, or change the PO.</>
        : summary?.suggestions.length
          ? "No PO is compared yet. Confirm a likely PO below, or choose another."
          : summary?.removed ? "The PO link was rejected. Choose a purchase order to compare against." : "No purchase order is linked. Choose one to compare against."}
    </p>

    {!link && summary?.suggestions.length ? <ul className="mt-2 space-y-1.5" aria-label="Likely purchase orders">
      {summary.suggestions.map((candidate) => <li key={candidate.matchId} className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-dashed border-slate-400 bg-white px-2.5 py-1.5 text-xs">
        <span className="text-slate-800">{describe(candidate)} <span className="text-slate-500">· {Math.round(candidate.confidence * 100)} % likely</span></span>
        <span className="flex gap-1.5">
          <button type="button" disabled={busy !== null} onClick={() => apply("confirm", () => confirmPoMatchAction(workspaceId, documentId, candidate.matchId))}
            className="inline-flex min-h-7 items-center rounded-md border border-emerald-300 bg-white px-2 font-medium text-emerald-800 hover:bg-emerald-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 disabled:opacity-60">Confirm</button>
          <button type="button" disabled={busy !== null} onClick={() => apply("reject", () => rejectPoMatchAction(workspaceId, documentId, candidate.matchId))}
            className="inline-flex min-h-7 items-center rounded-md border border-slate-300 bg-white px-2 font-medium text-slate-700 hover:bg-slate-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 disabled:opacity-60">Not this one</button>
        </span>
      </li>)}
    </ul> : null}

    <div className="mt-2 flex flex-wrap gap-1.5">
      {link?.kind === "auto" && <button type="button" disabled={busy !== null} onClick={() => apply("confirm", () => confirmPoMatchAction(workspaceId, documentId, link.matchId))}
        className="inline-flex min-h-8 items-center gap-1 rounded-md border border-emerald-300 bg-white px-2.5 text-xs font-medium text-emerald-800 hover:bg-emerald-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 disabled:opacity-60">
        {busy === "confirm" && <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden="true" />}Confirm {link.poNumber ?? "this PO"}
      </button>}
      <button type="button" disabled={busy !== null} onClick={openReplace}
        className="inline-flex min-h-8 items-center rounded-md border border-slate-300 bg-white px-2.5 text-xs font-medium text-slate-700 hover:bg-slate-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500 disabled:opacity-60">
        {link ? "Replace PO…" : "Choose a PO…"}
      </button>
      {link && <button type="button" disabled={busy !== null} onClick={() => setRejecting(true)}
        className="inline-flex min-h-8 items-center rounded-md border border-red-200 bg-white px-2.5 text-xs font-medium text-red-700 hover:bg-red-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500 disabled:opacity-60">
        Reject PO
      </button>}
    </div>

    {replacing && <div className="mt-2 rounded-md border border-slate-200 bg-white p-2">
      <div className="flex items-center gap-2">
        <label className="relative flex-1">
          <span className="sr-only">Search purchase orders</span>
          <Search className="pointer-events-none absolute left-2 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-500" aria-hidden="true" />
          <input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="PO number or supplier" autoFocus
            className="min-h-8 w-full rounded-md border border-slate-300 bg-white pl-7 pr-2 text-xs text-slate-800 placeholder:text-slate-500 focus:border-emerald-400 focus:outline-none focus:ring-2 focus:ring-emerald-100" />
        </label>
        <button type="button" onClick={() => setReplacing(false)} aria-label="Close the purchase order list" className="inline-flex h-8 w-8 items-center justify-center rounded text-slate-500 hover:bg-slate-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500"><X className="h-3.5 w-3.5" aria-hidden="true" /></button>
      </div>
      {candidates === null
        ? <p className="flex items-center gap-1.5 px-1 py-2 text-xs text-slate-600"><Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden="true" />Loading purchase orders…</p>
        : filtered.length === 0
          ? <p className="px-1 py-2 text-xs text-slate-600">{candidates.length === 0 ? "No purchase orders in this workspace yet. Add one on the Purchase Orders queue first." : "No purchase order matches that search."}</p>
          : <ul className="mt-1 max-h-48 divide-y divide-slate-100 overflow-y-auto" aria-label="Purchase orders">
            {filtered.slice(0, 30).map((candidate) => <li key={candidate.documentId}>
              <button type="button" disabled={busy !== null || candidate.documentId === link?.poDocumentId}
                onClick={async () => { const ok = await apply("replace", () => replacePoMatchAction(workspaceId, documentId, candidate.documentId)); if (ok) { setReplacing(false); toast.success(`Now comparing against ${candidate.poNumber ?? "the chosen PO"}.`) } }}
                className="flex min-h-8 w-full items-center justify-between gap-2 px-1.5 py-1 text-left text-xs text-slate-800 hover:bg-emerald-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-emerald-500 disabled:opacity-50">
                <span className="truncate">{describe(candidate)}</span>
                {candidate.documentId === link?.poDocumentId ? <span className="text-slate-500">current</span> : candidate.sameSupplier ? <span className="text-emerald-700">same supplier</span> : null}
              </button>
            </li>)}
          </ul>}
    </div>}

    <ConfirmDialog open={rejecting} title={`Reject ${link?.poNumber ?? "this purchase order"}?`}
      description="The invoice will no longer be compared against it: the PO cells clear and the Total's gate is re-evaluated. You can choose another PO afterwards. This is recorded on the audit trail."
      confirmLabel="Reject PO" onCancel={() => setRejecting(false)}
      onConfirm={async () => { setRejecting(false); if (link) { const ok = await apply("reject", () => rejectPoMatchAction(workspaceId, documentId, link.matchId)); if (ok) toast.success("PO rejected. Checks re-ran.") } }} />
  </section>
}

content.content:
  provenanceFields: Record<string, Ref>
  provenanceItems: Record<string, (Ref | null)[]>
  summaryFields: DocumentFieldDefinition[]
  rationales: Record<string, FieldRationale> | null
  checks: FieldCheck[]
  workspaceId: string
  documentId: string
  setTarget: (target: ProvenanceTarget) => void
}) {
  const navItems = formFields.map((field) => ({ key: field.key, confidence: fieldConfidence[field.key] ?? null, type: field.type }))
  const nav = useFieldNav(navItems)
  const formRef = useRef<HTMLFormElement>(null)
  const [liveChecks, setLiveChecks] = useState(checks)
  // One summary line in place of the per-field "Extracted" badges the audit had FieldRow drop:
  // says how many fields landed, and how many of those are worth a second look.
  const extractedCount = formFields.filter((field) => data[field.key] !== undefined && data[field.key] !== null && data[field.key] !== "").length

  const recompute = () => {
    if (!formRef.current) return
    setLiveChecks(rebuildLiveChecks(checks, parseLiveCheckValues(new FormData(formRef.current)), true))
  }

  const onEscalate = async (check: FieldCheck) => {
    setLiveChecks((prev) => prev.map((c) => (c.checkCode === check.checkCode ? { ...c, escalated: true } : c)))
    const result = await escalateCheckAction(workspaceId, documentId, check.checkCode)
    if (!result.success) toast.error(result.error || "Could not escalate this check")
  }

  return <form ref={formRef} action={saveReview} className="space-y-3" onKeyDown={nav.onFormKeyDown} onInput={recompute}>
    {extractedCount > 0 && <p className="text-xs text-slate-500">
      All {extractedCount} field{extractedCount === 1 ? "" : "s"} extracted{nav.totalSuspects > 0 ? ` — ${nav.totalSuspects} low-confidence` : ""}.
    </p>}
    {nav.totalSuspects > 0 && <div className="flex items-center justify-between rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
      <span><span className="font-semibold">{nav.suspectsRemaining}</span> of {nav.totalSuspects} low-confidence fields to review — Enter confirms and moves to the next.</span>
      <button type="button" className="rounded-md border border-amber-300 bg-white px-2 py-0.5 font-medium text-amber-800 hover:bg-amber-100" onClick={() => nav.focusNext()}>Next suspect</button>
    </div>}
    {formFields.map((field) => field.type === "array"
      ? <LineItemsSection key={field.key} field={field} value={data[field.key]} fieldKey={field.key} summaryFields={summaryFields} fieldValues={data} provenanceFields={provenanceFields} provenanceItems={provenanceItems[field.key] ?? []} onFocusSource={setTarget}
          checks={liveChecks.filter((check) => check.fields.some((f) => f === field.key || f.startsWith(`${field.key}[`)))} onEscalate={onEscalate} />
      : <FieldRow key={field.key} field={field} value={data[field.key]} confidence={fieldConfidence[field.key] ?? null} ref={provenanceFields[field.key] ?? null} onFocusSource={setTarget} rationale={rationales?.[field.key] ?? null}
          checks={liveChecks.filter((check) => checkAppliesToField(check, field.key))} onEscalate={onEscalate}
          registerNav={nav.registerField} isCurrent={nav.currentKey === field.key} isCompleted={nav.completedKeys.has(field.key)} />)}
    <div className="flex items-center gap-3 border-t border-slate-100 pt-3">
      <button type="submit" disabled={!docType} className="inline-flex items-center gap-2 rounded-lg bg-emerald-700 px-5 py-2 text-sm font-semibold text-white shadow-sm transition-colors hover:bg-emerald-800 focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-40" title={!docType ? "Choose Expense or Sale first" : undefined}>
        <CheckCircle2 className="h-4 w-4" />Save review
      </button>
      {!docType && <span className="text-xs text-amber-600">Choose a document type first</span>}
    </div>
  </form>
}

