import { beforeEach, describe, expect, it, vi } from "vitest"

vi.mock("@/lib/db", () => ({ prisma: {} }))
vi.mock("@/models/ledger-payments", () => ({ getDocumentPaymentStatuses: vi.fn().mockResolvedValue(new Map()) }))

