/** The breakdown surface. A popover anchored to the cell from `lg` up; a bottom sheet below it
 * (#228 Q14's 390 rule). Focus lands on the close control, Escape closes, focus returns to the
 * glyph that opened it. */
export function Breakdown({ title, sentence, rows, onClose, returnFocusTo, children }: {
  title: string
  sentence: string
  rows: BreakdownRow[]
  onClose: () => void
  returnFocusTo?: HTMLElement | null
  children?: ReactNode
}) {
  const closeRef = useRef<HTMLButtonElement>(null)
  useEffect(() => {
    closeRef.current?.focus()
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.stopPropagation(); onClose() } }
    document.addEventListener("keydown", onKey)
    return () => { document.removeEventListener("keydown", onKey); returnFocusTo?.focus() }
  }, [onClose, returnFocusTo])

  return <>
    <button type="button" aria-label="Close breakdown" onClick={onClose} className="fixed inset-0 z-30 bg-slate-900/30 lg:hidden" />
    <div role="dialog" aria-modal="false" aria-labelledby="po-breakdown-title"
      className="fixed inset-x-0 bottom-0 z-40 max-h-[70vh] overflow-y-auto rounded-t-2xl border border-slate-200 bg-white p-4 pb-[max(1rem,env(safe-area-inset-bottom))] shadow-[0_-8px_32px_-12px_rgba(15,23,42,0.25)] lg:absolute lg:inset-x-auto lg:bottom-auto lg:left-0 lg:top-full lg:mt-1 lg:w-80 lg:max-h-[min(24rem,calc(100vh-2rem))] lg:rounded-lg lg:p-3 lg:shadow-[0_12px_32px_-12px_rgba(15,23,42,0.35)]">

