"use client"

import { createContext, useContext } from "react"

export type PanelLayout = "split" | "source-only" | "details-only"

/** The Detail pane's source/details layout, shared with sections that need width. #250's View
 * PO row widens the details column while it is on (the compare cells and the PO line column
 * need it) and hands the split back when it is turned off — the header's own toggle always
 * wins over that. The default no-op provider keeps the section safe outside the pane. */
export const PaneLayoutContext = createContext<{ layout: PanelLayout; setLayout: (layout: PanelLayout) => void }>({ layout: "split", setLayout: () => {} })

export function usePaneLayout() {
  return useContext(PaneLayoutContext)
}

