    <div className="overflow-x-auto rounded-t-lg">
      <table className="w-full min-w-max border-collapse text-sm">
        <thead>
          <tr className="bg-slate-50">
            {columns.map((item) => <th key={item.key} scope="col" className={`border-b border-slate-200 px-2 py-1.5 text-xs font-semibold uppercase tracking-wide text-slate-500 ${item.type === "number" ? "text-right" : "text-left"}`}>
              {item.label}{item.required ? " *" : ""}
            </th>)}
            {poCompare && <th scope="col" className="border-b border-slate-200 px-2 py-1.5 text-left text-xs font-semibold uppercase tracking-wide text-slate-500">PO line</th>}
            <th scope="col" className="w-8 border-b border-slate-200" aria-label="Row actions" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => {
            const rowRef = provenanceItems?.[index] ?? null
            const line = lineByRow.get(index) ?? null
            return <tr key={row.id} className="group even:bg-slate-50/50 hover:bg-emerald-50/40">
            {columns.map((item) => {
              const inputId = `${fieldKey}-${row.id}-${item.key}`
              const name = `${fieldKey}[${index}][${item.key}]`
              const raw = row.values[item.key]
              const fieldPath = `${fieldKey}[${index}].${item.key}`
              const cellChecks = checks.filter((check) => check.fields.includes(fieldPath))
              const checkDescriptionId = `${fieldPath}-check-description`
              const cellId = `${fieldKey}-${row.id}-${item.key}`
              const compareCell = poCompare && line ? COMPARED_KEYS[item.key] ?? null : null
              const compareStatus = compareCell && line ? cellStatus(line, compareCell) : null
              const compareDescriptionId = `${fieldPath}-po-description`
              const breakdown = compareCell && line && openBreakdown?.cellId === cellId ? breakdownFor(line, compareCell, { currency: poCompare?.currency, invoiceHref: poCompare!.invoiceHref }) : null
              return <td key={item.key} className="relative border-b border-slate-100 p-0 align-top">
                {item.type === "boolean" ? (
                  <label className="flex h-full items-center justify-center gap-1.5 px-2 py-1.5 text-xs text-slate-600">
                    <input id={inputId} name={name} type="checkbox" aria-describedby={cellChecks.length ? checkDescriptionId : undefined} className="h-3.5 w-3.5 accent-emerald-600" value="true" defaultChecked={raw === true} />
                  </label>
                ) : item.type === "enum" ? (
                  <div className="relative flex items-center">
                    <select ref={(element) => { if (element) cellRefs.current.set(cellId, element); else cellRefs.current.delete(cellId) }} id={inputId} name={name} aria-describedby={cellChecks.length ? checkDescriptionId : undefined} defaultValue={typeof raw === "string" ? raw : ""} className={`${cellInputClass} appearance-none ${cellChecks.length ? "pr-8" : ""}`}>
                      <option value="">—</option>
                      {item.options?.map((option) => <option key={option} value={option}>{option}</option>)}
                    </select>
                    <span className="absolute right-1 top-1/2 -translate-y-1/2"><CheckGlyph checks={cellChecks} onOpen={() => setOpenCell(cellId)} /></span>
                  </div>
                ) : (
                  <div className="relative flex items-center">
                    <input ref={(element) => { if (element) cellRefs.current.set(cellId, element); else cellRefs.current.delete(cellId) }} id={inputId} name={name} type={item.type === "number" ? "number" : item.type === "date" ? "date" : "text"} step={item.type === "number" ? "any" : undefined}
                      aria-describedby={[cellChecks.length ? checkDescriptionId : null, compareStatus && compareStatus !== "not_compared" ? compareDescriptionId : null].filter(Boolean).join(" ") || undefined}
                      className={`${cellInputClass} ${item.type === "number" ? "text-right tabular-nums" : ""} ${cellChecks.length && !poCompare ? "pr-8" : ""}`}
                      defaultValue={typeof raw === "string" || typeof raw === "number" ? String(raw) : ""} />
                    {!poCompare && <span className="absolute right-1 top-1/2 -translate-y-1/2"><CheckGlyph checks={cellChecks} onOpen={() => setOpenCell(cellId)} /></span>}
                  </div>
                )}
                {compareCell && line && <div className={`flex items-center gap-1.5 px-2 pb-1.5 text-xs ${item.type === "number" ? "justify-end" : "justify-between"}`}>
                  <span className={`min-w-0 truncate tabular-nums ${compareStatus === "mismatch" ? "text-red-700" : "text-slate-500"}`} title={`On the PO: ${poValueFor(line, compareCell)}`}>
                    <span className={`mr-1 text-[10px] font-semibold uppercase tracking-wide ${compareStatus === "mismatch" ? "text-red-400" : "text-slate-400"}`}>PO</span>{poValueFor(line, compareCell)}
                  </span>
                  <span ref={(element) => { if (element) glyphRefs.current.set(cellId, element); else glyphRefs.current.delete(cellId) }} className="inline-flex">
                    <MatchGlyph status={compareStatus ?? "not_compared"} label={`${item.label}, line ${index + 1}`} describedBy={compareDescriptionId}
                      onOpen={() => setOpenBreakdown((current) => current?.cellId === cellId ? null : { cellId, rowIndex: index, cell: compareCell })} />
                  </span>
                  {compareStatus && compareStatus !== "not_compared" && <span id={compareDescriptionId} hidden>
                    {compareCell === "quantity" ? breakdownFor(line, "quantity", { invoiceHref: poCompare!.invoiceHref }).sentence : compareCell === "unit_price" ? breakdownFor(line, "unit_price", { invoiceHref: poCompare!.invoiceHref }).sentence : breakdownFor(line, "description", { invoiceHref: poCompare!.invoiceHref }).sentence}
                  </span>}
                </div>}
                {cellChecks.length > 0 && <span id={checkDescriptionId} hidden>{cellChecks.map((check) => check.stale ? `${check.message} Not rechecked after this edit.` : check.message).join(" ")}</span>}
                {openCell === cellId && <RationalePopover rationale={null} mismatchChecks={cellChecks} onClose={() => setOpenCell(null)} onFix={() => cellRefs.current.get(cellId)?.focus()} onEscalate={onEscalate} />}
                {breakdown && <Breakdown title={breakdown.title} sentence={breakdown.sentence} rows={breakdown.rows} onClose={() => setOpenBreakdown(null)} returnFocusTo={glyphRefs.current.get(cellId)?.querySelector("button") ?? null} />}
              </td>
            })}
            {poCompare && <td className="border-b border-slate-100 px-2 py-1.5 align-top">
              {poCompare.matchManually
                ? <label className="block">
                  <span className="sr-only">PO line for line {index + 1}</span>
                  <select value={poCompare.matchManually.assignments[String(index)] === undefined ? (line?.poLineIndex ?? "") : (poCompare.matchManually.assignments[String(index)] ?? "")}
                    onChange={(event) => poCompare.matchManually!.onAssign(index, event.target.value === "" ? null : Number(event.target.value))}
                    className="min-h-8 max-w-[14rem] rounded-md border border-slate-300 bg-white px-2 py-1 text-xs text-slate-800 focus:border-emerald-400 focus:outline-none focus:ring-2 focus:ring-emerald-100">
                    <option value="">No PO line</option>
                    {poCompare.poLineOptions.map((option) => <option key={option.index} value={option.index}>{option.label}</option>)}
                  </select>
                </label>
                : line ? <span className="flex items-center gap-1.5"><LineStatusPill status={line.status} />{line.assigned && <span className="text-[11px] text-slate-500" title="Matched by hand in Match manually">by hand</span>}</span>
                  : <span className="text-xs text-slate-500">Not compared</span>}
            </td>}
            <td className="border-b border-slate-100 px-1 text-center align-top">
              <div className="flex items-center gap-0.5 pt-1 opacity-0 focus-within:opacity-100 group-hover:opacity-100">
                {rowRef && onFocusSource && (
                  <button type="button" aria-label="View source" title="View source in document"
                    className="rounded p-1 text-emerald-500 hover:bg-emerald-50 hover:text-emerald-700"
                    onClick={() => onFocusSource({ page: rowRef.page, bbox: rowRef.bbox, quote: rowRef.quote })}>
                    <Crosshair className="h-3.5 w-3.5" />
                  </button>
                )}
                <button type="button" aria-label="Remove row" title="Remove row" disabled={rows.length <= 1}
                  className="rounded p-1 text-slate-500 hover:bg-red-50 hover:text-red-700 disabled:pointer-events-none disabled:opacity-0"
                  onClick={() => removeRow(row.id)}>
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            </td>
          </tr>})}
        </tbody>
      </table>
    </div>
    <button type="button" onClick={addRow}
      className="flex w-full items-center gap-1.5 border-t border-slate-200 bg-slate-50/50 px-2.5 py-1.5 text-xs font-medium text-slate-500 hover:bg-emerald-50 hover:text-emerald-700">
      <Plus className="h-3.5 w-3.5" />Add row
    </button>
  </div>
}

