import { chromium } from "playwright"
const WS = "af91555d-7450-4b21-a8ac-73db092617c8"
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto(`http://localhost:3000/workspaces/${WS}/invoices`, { waitUntil: "networkidle" })
await page.waitForTimeout(500)
const info = await page.evaluate(() => {
  const out = []
  document.querySelectorAll("tr.group").forEach((tr, i) => {
    if (i > 2) return
    const title = tr.querySelector("td:nth-of-type(3) span.inline-block.border-b-2") || tr.querySelector("td:nth-of-type(3) span.block.truncate")
    if (!title) { out.push({ i, none: true }); return }
    const r = title.getBoundingClientRect()
    const cx = r.left + r.width / 2, cy = r.top + r.height / 2
    const top = document.elementFromPoint(cx, cy)
    const sub = tr.querySelector("td:nth-of-type(3) span.block.truncate.text-xs")
    const sr = sub?.getBoundingClientRect()
    out.push({ i, text: title.textContent, rect: [r.left, r.top, r.width, r.height].map(Math.round), topEl: top?.tagName + "." + (top?.className || "").toString().slice(0, 60), subRect: sr ? [sr.left, sr.top, sr.width, sr.height].map(Math.round) : null, html: tr.querySelector("td:nth-of-type(3)")?.innerHTML.slice(0, 600) })
  })
  return out
})
console.log(JSON.stringify(info, null, 1))
await browser.close()

