import { chromium } from "playwright"
const WS = "af91555d-7450-4b21-a8ac-73db092617c8"
const INV = "10a4d716-56d4-4311-b322-7297262996d3"
const width = Number(process.argv[2] ?? 1440)
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width, height: width < 600 ? 844 : 900 } })
await page.goto(`http://localhost:3000/workspaces/${WS}/invoices/${INV}`, { waitUntil: "networkidle", timeout: 90000 })
await page.locator('button:has-text("Match manually")').first().waitFor({ timeout: 60000 })
await page.waitForTimeout(800)
const info = await page.evaluate(() => {
  const pane = document.querySelector("#queue-detail-pane")
  const paneRect = pane.getBoundingClientRect()
  const out = []
  pane.querySelectorAll("*").forEach((el) => {
    const cs = getComputedStyle(el)
    if (!["absolute", "fixed", "sticky"].includes(cs.position)) return
    const r = el.getBoundingClientRect()
    const beyond = r.left < paneRect.left - 1 || r.right > paneRect.right + 1 || r.top < paneRect.top - 1 || r.bottom > paneRect.bottom + 1
