1	"use server"
2	
3	import type { ActionState } from "@/lib/actions"
4	import { getCurrentUser } from "@/lib/auth"
5	import { confirmPoMatch, listPoCandidates, rejectPoMatch, replacePoMatch, setPoLineAssignments, summarizeInvoicePoLinks, type InvoicePoSummary } from "@/models/po-matching"
6	import { revalidatePath } from "next/cache"
7	import { errorMessage, NO_ACCESS, paths, requireMember } from "./action-helpers"
8	
9	/** #228 / #250: Match manually's server side. Every action is Server-confirmed (#228 Q14) — the
10	 * client changes nothing until the fresh summary comes back, so a refused or offline change
11	 * never shows a chip the server disagrees with. Any member who can edit the document may use
12	 * these (#228 Q13); an open Approval is sent back for review by the model layer. */
13	
14	export type PoMatchActionData = { summary: InvoicePoSummary | null; sentBack: boolean }
15	
16	function actorName(user: { name?: string | null; email?: string | null }): string {
17	  return user.name?.trim() || user.email || "a reviewer"
18	}
19	
20	async function afterChange(workspaceId: string, invoiceId: string, sentBack: boolean): Promise<ActionState<PoMatchActionData>> {
21	  const summaries = await summarizeInvoicePoLinks(workspaceId, [invoiceId])
22	  revalidatePath(`${paths(workspaceId).documents}/${invoiceId}`)
23	  revalidatePath(`/workspaces/${workspaceId}/invoices`)
24	  revalidatePath(`/workspaces/${workspaceId}/purchase-orders`)
25	  return { success: true, data: { summary: summaries.get(invoiceId) ?? null, sentBack } }
26	}
27	
28	export async function getInvoicePoSummaryAction(workspaceId: string, invoiceId: string): Promise<ActionState<InvoicePoSummary | null>> {
29	  const user = await getCurrentUser()
30	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
31	  const summaries = await summarizeInvoicePoLinks(workspaceId, [invoiceId])
32	  return { success: true, data: summaries.get(invoiceId) ?? null }
33	}
34	
35	export async function listPoCandidatesAction(workspaceId: string, invoiceId: string): Promise<ActionState<Awaited<ReturnType<typeof listPoCandidates>>>> {
36	  const user = await getCurrentUser()
37	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
38	  return { success: true, data: await listPoCandidates(workspaceId, invoiceId) }
39	}
40	
41	export async function confirmPoMatchAction(workspaceId: string, invoiceId: string, matchId: string): Promise<ActionState<PoMatchActionData>> {
42	  const user = await getCurrentUser()
43	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
44	  try {
45	    const { sentBack } = await confirmPoMatch({ workspaceId, invoiceId, matchId, actorId: user.id, actorName: actorName(user) })
46	    return afterChange(workspaceId, invoiceId, sentBack)
47	  } catch (error) {
48	    return { success: false, error: errorMessage(error, "Could not confirm the purchase order") }
49	  }
50	}
51	
52	export async function rejectPoMatchAction(workspaceId: string, invoiceId: string, matchId: string): Promise<ActionState<PoMatchActionData>> {
53	  const user = await getCurrentUser()
54	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
55	  try {
56	    const { sentBack } = await rejectPoMatch({ workspaceId, invoiceId, matchId, actorId: user.id, actorName: actorName(user) })
57	    return afterChange(workspaceId, invoiceId, sentBack)
58	  } catch (error) {
59	    return { success: false, error: errorMessage(error, "Could not reject the purchase order") }
60	  }
61	}
62	
63	export async function replacePoMatchAction(workspaceId: string, invoiceId: string, poDocumentId: string): Promise<ActionState<PoMatchActionData>> {
64	  const user = await getCurrentUser()
65	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
66	  try {
67	    const { sentBack } = await replacePoMatch({ workspaceId, invoiceId, poDocumentId, actorId: user.id, actorName: actorName(user) })
68	    return afterChange(workspaceId, invoiceId, sentBack)
69	  } catch (error) {
70	    return { success: false, error: errorMessage(error, "Could not replace the purchase order") }
71	  }
72	}
73	
74	export async function setPoLineAssignmentsAction(workspaceId: string, invoiceId: string, matchId: string, assignments: Record<string, number | null>): Promise<ActionState<PoMatchActionData>> {
75	  const user = await getCurrentUser()
76	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
77	  try {
78	    const { sentBack } = await setPoLineAssignments({ workspaceId, invoiceId, matchId, assignments, actorId: user.id, actorName: actorName(user) })
79	    return afterChange(workspaceId, invoiceId, sentBack)
80	  } catch (error) {
81	    return { success: false, error: errorMessage(error, "Could not save the line matches") }
82	  }
83	}
