export async function listPoCandidates(workspaceId: string, invoiceId: string): Promise<Array<{ documentId: string; poNumber: string | null; supplier: string | null; total: number | null; sameSupplier: boolean }>> {
  const invoice = await prisma.document.findFirst({ where: { id: invoiceId, workspaceId }, select: { reviewedData: true, rawExtraction: true } })
